function urgencyState(n){var due=n&&n.metadata&&n.metadata.due_at?new Date(n.metadata.due_at):null,age=(Date.now()-new Date(n&&n.created_at||Date.now()))/36e5,h=due&&!isNaN(due)?Math.ceil((due-new Date())/36e5):null;if(h!=null&&h<=24)return{level:'critical',label:h<0?'Overdue acknowledgement':'Urgent confirmation'};if(age>=36)return{level:'high',label:'Acknowledgement overdue'};if(age>=18)return{level:'watch',label:'Confirmation pending'};return{level:'new',label:'Updated'};}
