function fmtDate(v){if(!v)return'TBD';var d=new Date(v);if(isNaN(d))return String(v).slice(0,10);return d.toLocaleDateString([],{month:'short',day:'numeric',year:d.getFullYear()!==new Date().getFullYear()?'numeric':undefined});} function fmtTime(v){if(!v)return'';var d=new Date(v);return isNaN(d)?'':d.toLocaleTimeString([],{hour:'numeric',minute:'2-digit'});} function money(v,c){var n=Number(v||0);return new Intl.NumberFormat('en-US',{style:'currency',currency:c||'USD',maximumFractionDigits:0}).format(isFinite(n)?n:0);}
