function models(){return arr(boot().models);} function placementFor(id){return arr(boot().placements).find(function(p){return p.model_id===id;})||{};} function primaryMedia(x){var a=arr(x&&x.media);return (a.find(function(y){return y.is_primary;})||a[0]||{}).url||'';} function nameById(id){var x=models().find(function(m){return m.id===id;});return x&&x.display_name||'Model';}
