function bookingUsageFor(id){return arr(boot().finance&&boot().finance.booking_usage_terms).find(function(x){return x.booking_id===id;})||{};} function bookingRows(){return arr(boot().activity&&boot().activity.bookings).map(function(x){var b=x.bookings||{},u=bookingUsageFor(b.id),pay=(b.metadata&&b.metadata.payment_status)||'Not Invoiced';return {id:x.id,model_id:x.model_id,title:b.title||'Booking',date:b.starts_at,status:x.status||'pending',model_response:x.status||'pending',agency_status:b.status||'booking',response_at:x.response_at||null,call_time:b.call_time||b.starts_at,wrap_time:b.wrap_time||b.ends_at,usage:u.notes||'',payment_status:pay,sub:[b.location,x.role_label,b.travel_required?'Travel required':null,b.visa_required?'Visa required':null].filter(Boolean).join(' · '),booking:b};});} function castingRows(){return arr(boot().activity&&boot().activity.castings).map(function(x){var c=x.castings||{};return {id:x.id,model_id:x.model_id,title:c.title||'Casting',date:x.slot_at||c.starts_at,status:x.status||'invited',model_response:x.status||'invited',agency_status:c.status||'casting',response_at:x.response_at||null,deadline:c.deadline_at||c.ends_at||null,feedback:x.feedback||'',sub:[c.location,c.casting_type].filter(Boolean).join(' · '),casting:c};});}
