function pCalDate(v){var d=v instanceof Date?new Date(v.getTime()):new Date(v||Date.now());if(isNaN(d))d=new Date();d.setHours(0,0,0,0);return d;}
function pCalAdd(d,n){var x=pCalDate(d);x.setDate(x.getDate()+n);return x;}
function pCalKey(d){d=pCalDate(d);return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');}
function pCalMonday(d){var x=pCalDate(d),day=x.getDay(),diff=day===0?-6:1-day;return pCalAdd(x,diff);}
function partnerCalendarRows(){var out=[];bookingRows().forEach(function(x){out.push({kind:'booking',id:x.id,model_id:x.model_id,date:x.date,end:x.booking&&x.booking.ends_at,title:x.title,sub:[nameById(x.model_id),x.sub].filter(Boolean).join(' · '),status:x.status,details:x.booking||{}});});castingRows().forEach(function(x){out.push({kind:'casting',id:x.id,model_id:x.model_id,date:x.date,end:x.casting&&x.casting.ends_at,title:x.title,sub:[nameById(x.model_id),x.sub].filter(Boolean).join(' · '),status:x.status,details:x.casting||{}});});var b=boot();arr(b.schedule&&b.schedule.events).forEach(function(x){var e=x.events||{};if(!e.starts_at)return;out.push({kind:'event',id:x.id,record_id:e.id,model_id:x.model_id,date:e.starts_at,end:e.ends_at,title:e.title||'Agency Event',sub:[nameById(x.model_id),e.location,e.event_type].filter(Boolean).join(' · '),status:x.attendance_status||e.status,details:e});});arr(b.schedule&&b.schedule.availability_blocks).forEach(function(x){if(!x.starts_at)return;out.push({kind:'bookout',id:x.id,model_id:x.model_id,date:x.starts_at,end:x.ends_at,title:x.reason||'Model Bookout',sub:[nameById(x.model_id),x.block_type||'bookout'].filter(Boolean).join(' · '),status:x.status,details:x});});arr(b.schedule&&b.schedule.availability_requests).forEach(function(x){if(!x.starts_at||String(x.status)==='cancelled')return;out.push({kind:'availability',id:x.id,model_id:x.model_id,date:x.starts_at,end:x.ends_at,title:(x.request_type==='bookout'?'Bookout Request':'Availability Request'),sub:[nameById(x.model_id),x.reason].filter(Boolean).join(' · '),status:x.status,details:x});});arr(b.mobility&&b.mobility.travel).forEach(function(x){if(!x.starts_at)return;out.push({kind:'travel',id:x.id,model_id:x.model_id,date:x.starts_at,end:x.ends_at,title:x.purpose||[x.origin,x.destination].filter(Boolean).join(' → ')||'Travel',sub:[nameById(x.model_id),x.destination,x.status].filter(Boolean).join(' · '),status:x.status,details:x});});arr(b.mobility&&b.mobility.visa_cases).forEach(function(x){var d=x.appointment_at||x.hard_deadline;if(!d)return;out.push({kind:'visa',id:x.id,model_id:x.model_id,date:d,title:(x.country_code?x.country_code+' ':'')+(x.case_type||x.visa_type||'Visa'),sub:[nameById(x.model_id),x.appointment_at?'Consulate appointment':'Visa deadline'].filter(Boolean).join(' · '),status:x.status,details:x});});return out.sort(function(a,b){return String(a.date||'').localeCompare(String(b.date||''));});}
