function pCalRangeRows(rows,start,end){var a=pCalDate(start),z=pCalDate(end);z.setHours(23,59,59,999);return rows.filter(function(x){var d=new Date(x.date||0);return !isNaN(d)&&d>=a&&d<=z;});}
function pCalTitle(view,a){a=pCalDate(a);if(view==='month')return a.toLocaleDateString([],{month:'long',year:'numeric'});if(view==='week'){var st=pCalMonday(a),en=pCalAdd(st,6);return st.toLocaleDateString([],{month:'short',day:'numeric'})+' — '+en.toLocaleDateString([],{month:'short',day:'numeric',year:'numeric'});}if(view==='3day'){var en=pCalAdd(a,2);return a.toLocaleDateString([],{month:'short',day:'numeric'})+' — '+en.toLocaleDateString([],{month:'short',day:'numeric',year:'numeric'});}var en=pCalAdd(a,29);return a.toLocaleDateString([],{month:'short',day:'numeric'})+' — '+en.toLocaleDateString([],{month:'short',day:'numeric',year:'numeric'});}
function pCalToolbar(view,a){var views=[['agenda','Agenda'],['3day','3 Day'],['week','Week'],['month','Month']];return '<div class="v17p-cal-toolbar"><div class="v17p-cal-move"><button onclick="VEUX_PARTNER_V15.calendarMove(-1)">←</button><button onclick="VEUX_PARTNER_V15.calendarToday()">Today</button><button onclick="VEUX_PARTNER_V15.calendarMove(1)">→</button></div><strong>'+esc(pCalTitle(view,a))+'</strong><div class="v17p-cal-views">'+views.map(function(v){return '<button class="'+(view===v[0]?'on':'')+'" onclick="VEUX_PARTNER_V15.calendarView(\''+v[0]+'\')">'+v[1]+'</button>';}).join('')+'</div></div>';}
function pCalAgenda(rows,a){var st=pCalDate(a),en=pCalAdd(st,29),rs=pCalRangeRows(rows,st,en),groups={};rs.forEach(function(x){var k=pCalKey(x.date);(groups[k]||(groups[k]=[])).push(x);});var keys=Object.keys(groups).sort();if(!keys.length)return empty('No partner-visible activity in this 30-day agenda.');return '<div class="v17p-cal-agenda">'+keys.map(function(k){var d=new Date(k+'T12:00:00'),items=groups[k];return '<section><header><span>'+esc(d.toLocaleDateString([],{weekday:'short'}))+'</span><b>'+esc(d.toLocaleDateString([],{month:'short',day:'numeric'}))+'</b></header><div>'+items.map(pCalChip).join('')+'</div></section>';}).join('')+'</div>';}
function pCalDays(rows,start,count,cls){var days=[];for(var i=0;i<count;i++)days.push(pCalAdd(start,i));return '<div class="v17p-cal-scroll"><div class="v17p-cal-days '+cls+'">'+days.map(function(d){var rs=pCalRangeRows(rows,d,d);return '<section class="v17p-cal-day '+(pCalKey(d)===pCalKey(new Date())?'today':'')+'"><header><span>'+esc(d.toLocaleDateString([],{weekday:'short'}))+'</span><b>'+d.getDate()+'</b><em>'+esc(d.toLocaleDateString([],{month:'short'}))+'</em></header><div>'+rs.map(pCalChip).join('')+(rs.length?'':'<p class="v17p-cal-emptyday">No activity</p>')+'</div></section>';}).join('')+'</div></div>';}
function pCalMonth(rows,a){a=pCalDate(a);var first=new Date(a.getFullYear(),a.getMonth(),1),start=pCalMonday(first);if(start>first)start=pCalAdd(start,-7);var days=[];for(var i=0;i<42;i++)days.push(pCalAdd(start,i));return '<div class="v17p-cal-scroll"><div class="v17p-cal-month-head">'+['Mon','Tue','Wed','Thu','Fri','Sat','Sun'].map(function(x){return '<b>'+x+'</b>';}).join('')+'</div><div class="v17p-cal-month">'+days.map(function(d){var rs=pCalRangeRows(rows,d,d),outside=d.getMonth()!==a.getMonth();return '<section class="v17p-cal-cell '+(outside?'outside ':'')+(pCalKey(d)===pCalKey(new Date())?'today':'')+'"><header><b>'+d.getDate()+'</b></header><div>'+rs.slice(0,3).map(pCalChip).join('')+(rs.length>3?'<button class="v17p-cal-more" onclick="VEUX_PARTNER_V15.calendarJump(\''+pCalKey(d)+'\')">+'+(rs.length-3)+' more</button>':'')+'</div></section>';}).join('')+'</div></div>';}
function partnerCalendarView(v){S.calendarView=v;navTo('calendar');}
