function openPartnerMessageAlert(x){closePartnerMessageAlert();var conversationId=x&&x.metadata&&x.metadata.conversation_id||x&&x.source_id||'';if(x&&x.id&&window.VEUX_PARTNER&&VEUX_PARTNER.readNotification){VEUX_PARTNER.readNotification(x.id).catch(function(){});x.read_at=new Date().toISOString();syncNotificationBadge();}if(conversationId){S.thread=conversationId;navTo('messages');}}
function showPartnerMessageAlert(x){if(!x||!x.id)return;var last='';try{last=sessionStorage.getItem(PARTNER_MESSAGE_ALERT_KEY)||'';}catch(_e){}if(last===String(x.id))return;try{sessionStorage.setItem(PARTNER_MESSAGE_ALERT_KEY,String(x.id));}catch(_e){}closePartnerMessageAlert();var el=document.createElement('div');el.id='v16-message-alert';el.className='v16-message-alert';el.setAttribute('role','status');el.innerHTML='<span class="v16-message-dot"></span><div><b>'+esc(x.title||'New agency message')+'</b><p>'+esc(x.body||'Open Messages to view the conversation.')+'</p></div><button class="primary" type="button">Open Messages</button><button class="close" type="button" aria-label="Dismiss">×</button>';var buttons=el.querySelectorAll('button');buttons[0].onclick=function(){openPartnerMessageAlert(x);};buttons[1].onclick=closePartnerMessageAlert;document.body.appendChild(el);}
async function pollPartnerMessageAlerts(){if(document.visibilityState&&document.visibilityState==='hidden')return;try{var d=await VEUX_PARTNER.api('/api/portal/notifications?portal=partner&organization=maison-de-veux',{method:'GET'}),n=arr(d.notifications),b=boot();b.notifications=n;syncNotificationBadge();var msg=n.find(partnerIsMessageNotification);if(msg)showPartnerMessageAlert(msg);}catch(_e){}}
function installPartnerMessageAlerts(){if(partnerMessagePollTimer)return;setTimeout(pollPartnerMessageAlerts,1000);function cycle(){pollPartnerMessageAlerts();partnerMessagePollTimer=setTimeout(cycle,30000);}partnerMessagePollTimer=setTimeout(cycle,30000);window.addEventListener('focus',pollPartnerMessageAlerts);document.addEventListener('visibilitychange',function(){if(document.visibilityState==='visible')pollPartnerMessageAlerts();});}

function renderMessages(el){var b=boot(),c=arr(b.conversations),msgs=arr(b.messages);if(!S.thread&&c[0])S.thread=c[0].id;var sel=c.find(function(x){return x.id===S.thread;})||c[0],tm=sel?msgs.filter(function(x){return x.conversation_id===sel.id;}):[];el.innerHTML='<div class="v15p-page">'+pageHead('COMMUNICATIONS · PARTNER','Messages','Secure partner conversations with Maison de Veux.')+'<section class="v15p-card flush"><div class="v15p-thread-layout"><aside class="v15p-threads">'+c.map(function(x){var last=msgs.filter(function(m){return m.conversation_id===x.id;}).slice(-1)[0]||{};return '<button class="v15p-thread '+(sel&&sel.id===x.id?'on':'')+'" onclick="VEUX_PARTNER_V15.thread(\''+x.id+'\')"><b>'+esc(x.subject||'Agency Conversation')+'</b><span>'+esc((last.body||'No messages yet').slice(0,72))+'</span></button>';}).join('')+(c.length?'':empty('No conversations yet.'))+'</aside><div class="v15p-chat">'+(sel?'<div class="v15p-card-head" style="padding:14px 16px;margin:0;border-bottom:1px solid var(--v15p-line)"><b>'+esc(sel.subject||'Conversation')+'</b>'+status(sel.status)+'</div><div class="v15p-chat-scroll">'+tm.map(function(x){return '<div class="v15p-bubble '+(x.sender_user_id===b.current_user.id?'mine':'')+'"><small>'+esc(x.sender_label||'Agency')+' · '+esc(fmtDate(x.sent_at))+' '+esc(fmtTime(x.sent_at))+'</small><p>'+esc(x.body||'')+'</p></div>';}).join('')+'</div><div class="v15p-compose"><textarea id="v15p-reply" rows="2" placeholder="Write a message…"></textarea><button class="v15p-btn gold" onclick="VEUX_PARTNER_V15.reply(\''+sel.id+'\')">Send</button></div>':(c.length?empty('Select a conversation.'):'<div class="v15p-card-head" style="padding:14px 16px;margin:0;border-bottom:1px solid var(--v15p-line)"><b>New conversation · Maison de Veux</b></div><div class="v15p-chat-scroll">'+empty('No messages yet. Write to Maison de Veux below.')+'</div><div class="v15p-compose"><textarea id="v15p-reply" rows="2" placeholder="Write a message to Maison de Veux…"></textarea><button class="v15p-btn gold" onclick="VEUX_PARTNER_V15.startConversation()">Send</button></div>'))+'</div></div></section></div>';}
async function startConversation(){var ta=document.getElementById('v15p-reply'),body=(ta&&ta.value||'').trim();if(!body)return window.toast('Write a message first');try{var r=await VEUX_PARTNER.api('/api/partner/conversation-start',{method:'POST',body:JSON.stringify({organization_slug:'maison-de-veux'})});var id=r&&r.conversation&&r.conversation.id;if(!id)throw new Error('Conversation could not be opened.');await VEUX_PARTNER.sendMessage(id,body);S.thread=id;window.toast('Message sent');await VEUX_PARTNER.refresh();}catch(e){window.toast('Message failed: '+(e.message||e));}}
async function reply(id){var ta=document.getElementById('v15p-reply'),body=(ta&&ta.value||'').trim();if(!body)return window.toast('Write a message first');try{await VEUX_PARTNER.sendMessage(id,body);window.toast('Message sent');await VEUX_PARTNER.refresh();}catch(e){window.toast('Message failed: '+(e.message||e));}}
async function placementUpdate(id){if(!id)return window.toast('Placement record unavailable');var type=prompt('Update type: general, availability, travel, visa, documents or development','general')||'general',note=prompt('What should Maison de Veux know about this model / placement?')||'';if(!note.trim())return;try{await VEUX_PARTNER.api('/api/partner/placement-update',{method:'POST',body:JSON.stringify({organization_slug:'maison-de-veux',placement_id:id,update_type:type,note:note})});window.toast('Placement update shared with Maison de Veux');await VEUX_PARTNER.refresh();}catch(e){window.toast('Could not send placement update: '+(e.message||e));}}
function initPartnerAssistant(){if(document.getElementById('_v16p-ai'))return;var history=[],open=false,b=document.createElement('button');b.id='_v16p-ai';b.className='v16p-ai-btn';b.textContent='✦';b.title='VEUX Intelligence';document.body.appendChild(b);var p=document.createElement('section');p.id='_v16p-ai-panel';p.className='v16p-ai-panel';p.innerHTML='<header><div><small>VEUX DESK</small><b>Mother Agency Intelligence</b></div><button id="_v16p-ai-close">×</button></header><div id="_v16p-ai-msgs" class="v16p-ai-msgs"></div><footer><input id="_v16p-ai-input" placeholder="Ask about placements, travel, visa, approvals or commissions…"><button id="_v16p-ai-send">Send</button></footer>';document.body.appendChild(p);function toggle(){open=!open;p.classList.toggle('open',open);}function add(role,text){var d=document.createElement('div');d.className='v16p-ai-msg '+role;d.innerHTML='<small>'+(role==='user'?'You':'VEUX')+'</small><p>'+esc(text)+'</p>';document.getElementById('_v16p-ai-msgs').appendChild(d);d.parentNode.scrollTop=d.parentNode.scrollHeight;}async function send(){var i=document.getElementById('_v16p-ai-input'),msg=(i.value||'').trim();if(!msg)return;i.value='';add('user',msg);history.push({role:'user',content:msg});try{var r=await VEUX_PARTNER.api('/ask-claude',{method:'POST',body:JSON.stringify({message:msg,history:history.slice(-10),context:{page:S.page,model_id:S.modelId||null}})});add('assistant',r.reply||r.message||'No response generated.');history.push({role:'assistant',content:r.reply||r.message||''});}catch(e){add('assistant','I could not complete that request: '+(e.message||e));}}b.onclick=toggle;document.getElementById('_v16p-ai-close').onclick=toggle;document.getElementById('_v16p-ai-send').onclick=send;document.getElementById('_v16p-ai-input').addEventListener('keydown',function(e){if(e.key==='Enter')send();});add('assistant','I can help explain your models, placements, mobility, approvals, commissions and shared documents.');}
var R={home:renderHome,mymodels:renderModels,modeldetail:renderModelDetail,calendar:renderCalendar,castings:renderCastings,bookings:renderBookings,movement:renderMovement,visastatus:renderVisa,requests:renderApprovals,tasks:renderTasks,commissions:renderCommissions,documents:renderDocs,messages:renderMessages,notifications:renderNotifications};
function buildNav(){var sn=document.getElementById('sidenav'),mn=document.getElementById('mobnav'),ml=document.getElementById('mobMoreList');if(sn)sn.innerHTML=NAV.map(function(g){return '<div class="sn-grp"><div class="sn-h">'+esc(g.grp)+'</div>'+g.items.map(function(i){return '<button class="sn-b" data-p="'+i[0]+'" onclick="navTo(\''+i[0]+'\')"><span class="sn-ico">'+i[2]+'</span>'+esc(i[1])+'</button>';}).join('')+'</div>';}).join('');var flat=NAV.reduce(function(a,g){return a.concat(g.items);},[]),prim=['home','mymodels','requests','tasks'],p=flat.filter(function(i){return prim.indexOf(i[0])>-1;}),sec=flat.filter(function(i){return prim.indexOf(i[0])<0;});if(mn)mn.innerHTML=p.map(function(i){return '<button class="mn-b" data-p="'+i[0]+'" onclick="navTo(\''+i[0]+'\')"><span class="mn-b-ico">'+i[2]+'</span><span class="mn-b-lbl">'+esc(i[1])+'</span></button>';}).join('')+'<button class="mn-b" id="mn-more-btn" onclick="openMobMore()"><span class="mn-b-ico">•••</span><span class="mn-b-lbl">More</span><span class="mn-more-dot" id="mn-more-dot"></span></button>';if(ml)ml.innerHTML=sec.map(function(i){return '<div class="mob-more-item" data-p="'+i[0]+'" onclick="navTo(\''+i[0]+'\');closeMobMore()"><span class="mob-more-item-ico">'+i[2]+'</span><span class="mob-more-item-lbl">'+esc(i[1])+'</span></div>';}).join('');}
function setActive(p){document.querySelectorAll('.sn-b,.mn-b,.mob-more-item').forEach(function(x){x.classList.toggle('on',x.dataset.p===p);});var secondary=Array.from(document.querySelectorAll('.mob-more-item')).some(function(x){return x.dataset.p===p;}),more=document.getElementById('mn-more-btn'),dot=document.getElementById('mn-more-dot');if(more)more.classList.toggle('on',secondary);if(dot)dot.classList.toggle('show',secondary);}
var PARTNER_NAV_STATE_KEY='veux-ma-nav-state-v1',PARTNER_NAV_STACK_KEY='veux-ma-nav-stack-v1';
function partnerNavRead(key,fallback){try{var raw=sessionStorage.getItem(key);return raw?JSON.parse(raw):fallback;}catch(_e){return fallback;}}
function partnerNavWrite(key,value){try{sessionStorage.setItem(key,JSON.stringify(value));}catch(_e){}}
function partnerNavState(page){return {veuxPortal:'partner',page:page||S.page||'home',thread:S.thread||null,modelId:S.modelId||null,calendarView:S.calendarView||'agenda',calendarDate:S.calendarDate||null};}
function partnerApplyNavState(st){if(!st)return;if(st.thread)S.thread=st.thread;if(st.modelId)S.modelId=st.modelId;if(st.calendarView)S.calendarView=st.calendarView;if(st.calendarDate)S.calendarDate=st.calendarDate;}
function partnerPushPrevious(next){var prev=partnerNavRead(PARTNER_NAV_STATE_KEY,null);if(!prev||!prev.page||prev.page===next)return;var stack=partnerNavRead(PARTNER_NAV_STACK_KEY,[]);if(!Array.isArray(stack))stack=[];var tail=stack[stack.length-1];if(!tail||tail.page!==prev.page||tail.thread!==prev.thread||tail.modelId!==prev.modelId)stack.push(prev);if(stack.length>40)stack=stack.slice(-40);partnerNavWrite(PARTNER_NAV_STACK_KEY,stack);}
window.portalBack=function(){var stack=partnerNavRead(PARTNER_NAV_STACK_KEY,[]);if(!Array.isArray(stack))stack=[];var target=stack.pop()||{veuxPortal:'partner',page:'home'};partnerNavWrite(PARTNER_NAV_STACK_KEY,stack);partnerApplyNavState(target);return navTo(target.page||'home',{skipPortalStack:true,historyMode:'replace',restoreState:target});};
function navTo(p,opts){opts=opts||{};if(!DIRECT.has(p))p='home';if(opts.restoreState)partnerApplyNavState(opts.restoreState);if(!opts.skipPortalStack)partnerPushPrevious(p);var pm=document.getElementById('pm');if(!pm)return;document.querySelectorAll('#pm .panel').forEach(function(x){x.classList.remove('on');});var el=document.getElementById('p-'+p);if(!el){el=document.createElement('div');el.id='p-'+p;el.className='panel';pm.appendChild(el);}el.classList.add('on');S.page=p;window._currentPage=p;var saved=partnerNavState(p);partnerNavWrite(PARTNER_NAV_STATE_KEY,saved);try{var url=location.pathname+location.search+location.hash;if(opts.historyMode==='replace'||!history.state||history.state.veuxPortal!=='partner')history.replaceState(saved,document.title,url);else if(!opts.fromPopState)history.pushState(saved,document.title,url);}catch(_e){}syncNotificationBadge();setActive(p);closeMobMore();if(typeof window.closeSB==='function')window.closeSB();var fn=R[p];try{if(fn)fn(el);else el.innerHTML='<div class="v15p-page">'+pageHead('MOTHER AGENCY PORTAL','Page unavailable','This route has not been enabled in the first-class partner portal.')+'</div>';}catch(renderError){console.error('[VEUX MA 16.7.14] page render failed',p,renderError);el.innerHTML='<div class="v15p-page">'+pageHead('MOTHER AGENCY PORTAL','Page could not finish loading','This page hit a recoverable render error.',btn('Retry','navTo(\''+p+'\')',true))+'<div class="v15p-empty">'+esc(renderError&&renderError.message||'Render failed')+'</div></div>';}pm.scrollTop=0;}
function launch(){var b=boot(),partner=b.partner||{},company=partner.companies||{},u=b.current_user||{},name=company.name||partner.name||u.email||'Mother Agency',role='Mother Agency Partner',av=document.getElementById('tbAv'),nm=document.getElementById('tbName'),rl=document.getElementById('tbRole'),app=document.getElementById('app');if(app){app.style.display='block';app.classList.add('on');}if(av)av.textContent=name.split(/\s+/).slice(0,2).map(function(x){return x[0]||'';}).join('').toUpperCase();if(nm)nm.textContent=name;if(rl)rl.textContent=role;var mark=document.querySelector('.tb-mark'),tag=document.querySelector('.tb-tag');if(mark)mark.innerHTML='VEUX DESK';if(tag)tag.textContent='MOTHER AGENCY';var cp=document.getElementById('_changepass');if(cp)cp.style.display='none';buildNav();syncNotificationBadge();var restored=partnerNavRead(PARTNER_NAV_STATE_KEY,null);if(restored&&!DIRECT.has(restored.page))restored=null;if(restored)partnerApplyNavState(restored);navTo(restored&&restored.page||S.page||'home',{skipPortalStack:true,historyMode:'replace',restoreState:restored});initPartnerAssistant();installPartnerMessageAlerts();window.dispatchEvent(new CustomEvent('veux:partner-v16-ready',{detail:{version:'16.7.14',direct:Array.from(DIRECT),partnerSafe:true,placementUpdates:true,threeWaySync:true,smartCalendar:true}}));}
window.addEventListener('popstate',function(e){var st=e&&e.state;if(st&&st.veuxPortal==='partner'&&st.page){partnerApplyNavState(st);navTo(st.page,{skipPortalStack:true,fromPopState:true,restoreState:st});}});
function closeSB(){var s=document.getElementById('sidenav'),o=document.getElementById('sb-ov');if(s)s.classList.remove('open');if(o)o.classList.remove('show');}function toggleSB(){var s=document.getElementById('sidenav'),o=document.getElementById('sb-ov');if(!s)return;var on=!s.classList.contains('open');s.classList.toggle('open',on);if(o)o.classList.toggle('show',on);}
function closeMobMore(){var s=document.getElementById('mobMoreSheet'),o=document.getElementById('mobMoreOv');if(s)s.classList.remove('open');if(o)o.classList.remove('show');} function openMobMore(){var s=document.getElementById('mobMoreSheet'),o=document.getElementById('mobMoreOv');if(s)s.classList.add('open');if(o)o.classList.add('show');}
var _v15ReturnRefreshAt=0;function v15ReturnRefresh(){var now=Date.now();if(now-_v15ReturnRefreshAt<4000)return;var app=document.getElementById('app');if(!app||!app.classList.contains('on'))return;if(document.visibilityState&&document.visibilityState==='hidden')return;_v15ReturnRefreshAt=now;try{if(window.VEUX_PARTNER&&VEUX_PARTNER.refresh)VEUX_PARTNER.refresh();}catch(_e){}}window.addEventListener('online',v15ReturnRefresh);window.addEventListener('focus',v15ReturnRefresh);document.addEventListener('visibilitychange',function(){if(document.visibilityState==='visible')v15ReturnRefresh();});
window.launch=launch;window.navTo=navTo;window.toggleSB=toggleSB;window.closeSB=closeSB;window.rerender=function(p){navTo(p||S.page,{skipPortalStack:true,historyMode:'replace'});};window.buildNav=buildNav;window.openMobMore=openMobMore;window.closeMobMore=closeMobMore;window.signOut=function(){try{sessionStorage.removeItem(PARTNER_NAV_STATE_KEY);sessionStorage.removeItem(PARTNER_NAV_STACK_KEY);sessionStorage.removeItem(PARTNER_MESSAGE_ALERT_KEY);}catch(_e){}return window.VEUX_PARTNER&&VEUX_PARTNER.signOut?VEUX_PARTNER.signOut():undefined;};window.toast=window.toast||function(msg){var t=document.createElement('div');t.className='toast';t.textContent=msg;document.body.appendChild(t);setTimeout(function(){t.remove();},2200);};
